begin;
create function pg_temp.assert_cohort(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end$$;
insert into auth.users(id,email,raw_app_meta_data) values
 ('22222222-2222-4222-8222-222222222222','identity-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa@members.valuelog.invalid','{"identity_issuer":"word-wallet-web","identity_did":"did:iov:member:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'),
 ('33333333-3333-4333-8333-333333333333','identity-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb@members.valuelog.invalid','{"identity_issuer":"word-wallet-web","identity_did":"did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}');
select public.admit_value_log_member('22222222-2222-4222-8222-222222222222','did:iov:member:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','identity-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa@members.valuelog.invalid');
select public.admit_value_log_member('33333333-3333-4333-8333-333333333333','did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','identity-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb@members.valuelog.invalid');
select public.setup_value_log_member('22222222-2222-4222-8222-222222222222','Synthetic A','Asia/Kolkata');
select public.setup_value_log_member('33333333-3333-4333-8333-333333333333','Synthetic B','Europe/London');
do $$declare actor uuid:='11111111-1111-4111-8111-111111111111';a uuid:='22222222-2222-4222-8222-222222222222';b uuid:='33333333-3333-4333-8333-333333333333'; d uuid:=gen_random_uuid();r uuid:=gen_random_uuid();lease uuid:=gen_random_uuid();delegation uuid;claim jsonb;cipher jsonb:='{"ciphertext":"syntheticencryptedtext","iv":"iiiiiiiiiiiiiiii","authTag":"tttttttttttttttttttttttt","keyVersion":1,"digest":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}';receipt jsonb:='{"kind":"cohort_review_pending"}';starttime timestamptz:=date_trunc('day',now())-interval '1 day';
begin
 begin perform cohort_command(a,'create_community','{"id":"wrong","name":"Wrong","kind":"work"}');raise exception 'FAIL: member became admin';exception when raise_exception then if sqlerrm<>'UNAUTHORIZED' then raise;end if;end;
 perform cohort_command(actor,'create_community','{"id":"field_work","name":"Synthetic project","kind":"work"}');
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('a',64),'did','did:iov:member:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','communities',jsonb_build_array('field_work')));
 begin perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('a',64),'house','house_of_sis','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));raise exception 'FAIL: bound invitation stolen';exception when raise_exception then if sqlerrm<>'UNAUTHORIZED' then raise;end if;end;
 begin perform cohort_command(a,'enroll',jsonb_build_object('hash',repeat('a',64),'house','house_of_sis','communities','[]'::jsonb));raise exception 'FAIL: missing consent accepted';exception when raise_exception then if sqlerrm<>'CONSENT_REQUIRED' then raise;end if;end;
 perform cohort_command(a,'enroll',jsonb_build_object('hash',repeat('a',64),'house','house_of_sis','communities',jsonb_build_array('field_work'),'consent',true,'startingValuesConfirmed',true));
 perform cohort_command(actor,'invite',jsonb_build_object('id',gen_random_uuid(),'hash',repeat('b',64),'communities','[]'::jsonb));
 perform cohort_command(b,'enroll',jsonb_build_object('hash',repeat('b',64),'house','house_of_bros','communities','[]'::jsonb,'consent',true,'startingValuesConfirmed',true));
 perform pg_temp.assert_cohort((select count(*)=2 from cohort_enrollments),'two enrolled people');
 perform pg_temp.assert_cohort((select house_id='house_of_sis' and policy_id='field-station-assumed-700-v1' from cohort_enrollments where owner_id=a),'chosen house and provisional policy');
 perform pg_temp.assert_cohort((select count(*)=0 from founder_wellbeing_baseline_epochs where owner_id in(a,b)),'no founder baseline inherited');
 perform public.save_native_log_draft(a,d,0,cipher);
 select boundary_at into starttime from cohort_enrollments where owner_id=a;
 -- Zero elapsed time just after enrollment is avoided using a future-independent interval earlier in its local day.
 if now()-starttime<interval '2 minutes' then starttime:=now()-interval '1 minute';update cohort_enrollments set boundary_at=starttime where owner_id=a;end if;
 perform confirm_cohort_log(a,d,1,repeat('a',64),'Explicit approval',jsonb_build_array(jsonb_build_object('id',r,'occurrenceId',gen_random_uuid(),'start',starttime,'end',starttime+interval '30 seconds','content',cipher)),receipt);
 perform pg_temp.assert_cohort(confirm_cohort_log(a,d,1,repeat('a',64),'Explicit approval','[]',receipt)=receipt,'confirmation retry returns same receipt');
 perform pg_temp.assert_cohort((select count(*)=1 from cohort_records where owner_id=a),'one occurrence after retry');
 perform cohort_command(actor,'assign_operator','{"did":"did:iov:member:bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}');
 perform cohort_command(b,'accept_operator','{"consent":true}');
 claim:=claim_cohort_review(a,r,lease);delegation:=(claim->'delegation'->>'id')::uuid;
 perform pg_temp.assert_cohort(claim is not null and claim_cohort_review(a,r,gen_random_uuid()) is null,'one-use review claim');
 perform cohort_command(a,'consent','{"consent":false}');
 perform pg_temp.assert_cohort(not finish_cohort_review(a,r,lease,delegation,repeat('a',64),gen_random_uuid(),'reviewed',cipher),'revoked consent stops queued review');
 perform cohort_command(a,'consent','{"consent":true}');
 update cohort_records set lease_until=now()-interval '1 second' where id=r;
 lease:=gen_random_uuid();claim:=claim_cohort_review(a,r,lease);delegation:=(claim->'delegation'->>'id')::uuid;
 perform pg_temp.assert_cohort(finish_cohort_review(a,r,lease,delegation,repeat('a',64),gen_random_uuid(),'reviewed',cipher),'current approved input can be reviewed');
 perform pg_temp.assert_cohort(not finish_cohort_review(a,r,lease,delegation,repeat('a',64),gen_random_uuid(),'reviewed',cipher),'review retry cannot append twice');
 perform cohort_command(a,'appeal',jsonb_build_object('id',gen_random_uuid(),'recordId',r,'content',cipher));
 begin perform cohort_command(actor,'human_review',jsonb_build_object('id',gen_random_uuid(),'recordId',r,'digest',repeat('a',64),'permissionsRevision',-1,'content',cipher));raise exception 'FAIL: stale human permission read committed';exception when raise_exception then if sqlerrm<>'REVISION_CONFLICT' then raise;end if;end;
 perform cohort_command(actor,'human_review',jsonb_build_object('id',gen_random_uuid(),'recordId',r,'digest',repeat('a',64),'permissionsRevision',(select permissions_revision from cohort_enrollments where owner_id=a),'content',cipher));
 perform pg_temp.assert_cohort(not promote_cohort_replay(a,-1,gen_random_uuid(),repeat('a',64),repeat('b',64),cipher),'stale replay cannot promote');
 perform pg_temp.assert_cohort(promote_cohort_replay(a,(select revision from cohort_enrollments where owner_id=a),gen_random_uuid(),repeat('a',64),repeat('b',64),cipher),'verified replay can promote');
 perform pg_temp.assert_cohort(promote_cohort_replay(a,(select revision from cohort_enrollments where owner_id=a),gen_random_uuid(),repeat('a',64),repeat('b',64),cipher),'identical replay is idempotent');
 perform pg_temp.assert_cohort((select count(*)=1 from cohort_replay_runs where owner_id=a),'duplicate replay retains one verified run');
 perform pg_temp.assert_cohort((select calculated_revision=revision from cohort_enrollments where owner_id=a),'calculation catch-up revision recorded');
 begin perform promote_cohort_replay(a,(select revision from cohort_enrollments where owner_id=a),gen_random_uuid(),repeat('a',64),repeat('c',64),cipher);raise exception 'FAIL: same input changed output';exception when raise_exception then if sqlerrm<>'REPLAY_VERIFICATION_FAILED' then raise;end if;end;
end$$;
set local role authenticated;
set local request.jwt.claim.sub='33333333-3333-4333-8333-333333333333';
select pg_temp.assert_cohort((select count(*)=0 from cohort_records),'B cannot read A records');
select pg_temp.assert_cohort((select count(*)=1 from cohort_enrollments),'B sees only own enrollment');
select pg_temp.assert_cohort(not has_function_privilege(current_user,'public.cohort_command(uuid,text,jsonb)','EXECUTE'),'browser cannot call privileged cohort command');
select pg_temp.assert_cohort(not has_table_privilege(current_user,'public.cohort_review_events','INSERT'),'browser cannot invent review');
reset role;
select 'PASS: cohort membership, consent, invitation binding, owner isolation, review leases and founder preservation' as result;
rollback;
